Here is an implementation of a personal database class in Python to store customer details: ```python class Customer: def __init__(self, name, email, phone, address): self.name = name self.email = email self.phone = phone self.address = address def __str__(self): return "Name: {} 
Email: {} 
Phone: {} 
Address: {}
".format(self.name, self.email, self.phone, self.address) class Database: def __init__(self): self.customers = [] def add_customer(self, name, email, phone, address): customer = Customer(name, email, phone, address) self.customers.append(customer) def remove_customer(self, name): for customer in self.customers: if customer.name == name: self.customers.remove(customer) return True return False def update_customer(self, old_name, new_name, email, phone, address): for customer in self.customers: if customer.name == old_name: customer.name = new_name customer.email = email customer.phone = phone customer.address = address return True return False def search_customer(self, name): for customer in self.customers: if customer.name == name: return customer return None def get_customers(self): return self.customers[:] # Example usage: database = Database() # Add customers: database.add_customer("John Doe", "john@example.com", "123-4567", "123 Main St.") database.add_customer("Jane Doe", "jane@example.com", "876-5432", "456 Park Ave.") database.add_customer("Jim Smith", "jim@example.com", "987-6543", "789 Elm St.") # Remove a customer: database.remove_customer("Jim Smith") # Update a customer's details: database.update_customer("John Doe", "John Smith", "john-new@example.com", "987-6543", "123 Main St. Apt. 5") # Search for a customer: customer = database.search_customer("Jane Doe") if customer: print(customer) # Get all customers: customers = database.get_customers() for customer in customers: print(customer) ``` This implementation uses classes to represent a customer and a database. The `Customer` class has attributes for name, email, phone, and address. The `Database` class has a list to store customers and methods to add, remove, update, search, and get all customers.
